class Base {
public:
  virtual void mf1() const;
  virtual void mf2(int x);
  virtual void mf3() &;
  void mf4() const; // Not virtual
};

class Derived : public Base {
public:
  // All of the following declarations would cause a compile error because 'override'
  // is used and the signatures do not match a base class virtual function.

  virtual void mf1() override; // ERROR: Not marked const
  virtual void mf2(unsigned int x) override; // ERROR: Parameter type is different
  virtual void mf3() && override; // ERROR: Ref-qualifier is different
  void mf4() const override; // ERROR: Base::mf4 is not virtual
};
